USE sentinel_ai_security;
CREATE TABLE IF NOT EXISTS notifications (
    notification_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, recipient_user_id BIGINT UNSIGNED NULL, recipient_employee_id BIGINT UNSIGNED NULL, alert_id BIGINT UNSIGNED NULL, event_type VARCHAR(120) NOT NULL, severity ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW', title VARCHAR(255) NOT NULL, message VARCHAR(2000) NOT NULL, read_at DATETIME NULL, sent_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_notifications_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_notifications_recipient_user FOREIGN KEY (recipient_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_notifications_recipient_employee FOREIGN KEY (recipient_employee_id) REFERENCES employees(employee_id) ON DELETE SET NULL, CONSTRAINT fk_notifications_alert FOREIGN KEY (alert_id) REFERENCES alerts(alert_id) ON DELETE SET NULL,
    INDEX idx_notifications_company_user_read (company_id,recipient_user_id,read_at), INDEX idx_notifications_company_employee_read (company_id,recipient_employee_id,read_at), INDEX idx_notifications_company_created_at (company_id,created_at), INDEX idx_notifications_company_alert (company_id,alert_id)
);
CREATE TABLE IF NOT EXISTS notification_deliveries (
    notification_delivery_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, notification_id BIGINT UNSIGNED NOT NULL, channel ENUM('IN_APP','EMAIL','SMS','WHATSAPP') NOT NULL DEFAULT 'IN_APP', destination_reference VARCHAR(255) NULL, delivery_status ENUM('PENDING','SENT','FAILED','CANCELLED') NOT NULL DEFAULT 'PENDING', attempt_count INT UNSIGNED NOT NULL DEFAULT 0, next_attempt_at DATETIME NULL, sent_at DATETIME NULL, failed_at DATETIME NULL, error_code VARCHAR(100) NULL, error_message VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_notification_deliveries_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_notification_deliveries_notification FOREIGN KEY (notification_id) REFERENCES notifications(notification_id) ON DELETE RESTRICT,
    INDEX idx_notification_deliveries_company_status (company_id,delivery_status), INDEX idx_notification_deliveries_company_notification (company_id,notification_id), INDEX idx_notification_deliveries_next_attempt (company_id,next_attempt_at)
);